const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const { createAdapter } = require('@socket.io/redis-adapter');
const { Redis } = require('ioredis');
const { OrganizationService } = require('../services/orgService');

const app = express();
app.use(express.json());
const server = http.createServer(app);

const io = new Server(server);
const pubClient = new Redis(process.env.REDIS_URL);
const subClient = pubClient.duplicate();
io.adapter(createAdapter(pubClient, subClient));

app.post('/api/notifications/namespace-broadcast', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { targetNamespace, alertTitle, alertMessage, severity } = req.body;

  if (!targetNamespace || !alertMessage) {
    return res.status(400).json({ error: 'targetNamespace and alertMessage required' });
  }

  // Verify that caller has administrative broadcast rights for the specific target namespace
  const hasBroadcastRights = await OrganizationService.verifyNamespaceAdmin(
    req.user.id,
    targetNamespace
  );

  if (!hasBroadcastRights) {
    return res.status(403).json({ error: 'Access denied: caller cannot broadcast to this namespace' });
  }

  io.of(targetNamespace).emit('emergency_alert', {
    title: alertTitle,
    message: alertMessage,
    severity: severity || 'MEDIUM',
    senderId: req.user.id,
    timestamp: new Date().toISOString()
  });

  res.json({ success: true, broadcastedTo: targetNamespace });
});

server.listen(4003);
